mapper.select:
SELECT ao.id, ao.abnormal_code AS abnormalCode, ol.id AS orderId, ao.order_code AS orderCode, ol.plate_no AS plateNo, cs.station_name AS stationName, ao.abnormal_type AS abnormalType, ao.abnormal_reason AS abnormalReason, ao.handle_measure AS handleMeasure, ao.refund_amount AS refundAmount, ao.refund_reason AS refundReason, UNIX_TIMESTAMP(ao.check_time) * 1000 AS checkTime, UNIX_TIMESTAMP(ao.abnormal_time) * 1000 AS abnormalTime, ao.abnormal_status AS abnormalStatus, su1.nickname AS verifyUser, UNIX_TIMESTAMP(ao.verify_time) * 1000 AS verifyTime, ao.verify_result AS verifyResult, ao.verify_remark AS verifyRemark, su2.nickname AS handleUser, UNIX_TIMESTAMP(ao.handle_time) * 1000 AS handleTime, su3.nickname AS checkUser, UNIX_TIMESTAMP(ao.complete_time) * 1000 AS completeTime, ao.remark, -- 修复：如果关联不到用户，回退显示原始字段值（可能是空字符串） COALESCE(cr.nickname, ao.creator) AS creator, COALESCE(cu.nickname, ao.updater) AS updater, UNIX_TIMESTAMP(ao.create_time) * 1000 AS createTime, UNIX_TIMESTAMP(ao.update_time) * 1000 AS updateTime FROM abnormal_order ao LEFT JOIN order_list ol ON ao.order_code = ol.order_code COLLATE utf8mb4_general_ci AND ol.deleted = 0 LEFT JOIN charging_pile cp ON ol.pile_code = cp.pile_code COLLATE utf8mb4_general_ci AND cp.deleted = 0 LEFT JOIN charging_station cs ON cp.station_id = cs.id AND cs.deleted = 0 LEFT JOIN sys_user su1 ON ao.verify_user = su1.id LEFT JOIN sys_user su2 ON ao.handle_user = su2.id LEFT JOIN sys_user su3 ON ao.check_user = su3.id -- 创建人关联（creator存的是用户ID） LEFT JOIN sys_user cr ON cr.id IS NOT NULL AND ao.creator IS NOT NULL AND ao.creator != '' AND cr.id = CAST(ao.creator AS UNSIGNED) -- 更新人关联 LEFT JOIN sys_user cu ON cu.id IS NOT NULL AND ao.updater IS NOT NULL AND ao.updater != '' AND cu.id = CAST(ao.updater AS UNSIGNED) WHERE ao.deleted = 0
AND ao.abnormal_code LIKE CONCAT('%', #{req.abnormalCode}, '%')
AND ao.order_code LIKE CONCAT('%', #{req.orderCode}, '%')
AND ol.plate_no LIKE CONCAT('%', #{req.plateNo}, '%')
AND ao.abnormal_type = #{req.abnormalType}
AND ao.abnormal_status = #{req.abnormalStatus}
AND ao.create_time >= #{req.startTime}
AND ao.create_time <= #{req.endTime}

SELECT DATE(a.abnormal_time) AS date, COUNT(a.id) AS abnormalCount, SUM(CASE WHEN a.complete_time IS NOT NULL THEN 1 ELSE 0 END) AS handleCount FROM abnormal_order a LEFT JOIN order_list o ON a.order_code = o.order_code COLLATE utf8mb4_unicode_ci LEFT JOIN charging_pile p ON o.pile_code = p.pile_code COLLATE utf8mb4_unicode_ci LEFT JOIN charging_station s ON p.station_id = s.id WHERE a.deleted = 0 AND DATE(a.abnormal_time) BETWEEN #{startTime} AND #{endTime}
AND s.id = #{stationId}
GROUP BY DATE(a.abnormal_time) ORDER BY DATE(a.abnormal_time) ASC

SELECT t.type, t.count, ROUND((t.count / total.totalCount) * 100, 2) AS ratio FROM ( SELECT a.abnormal_type AS type, COUNT(a.id) AS count FROM abnormal_order a LEFT JOIN order_list o ON a.order_code = o.order_code COLLATE utf8mb4_unicode_ci LEFT JOIN charging_pile p ON o.pile_code = p.pile_code COLLATE utf8mb4_unicode_ci LEFT JOIN charging_station s ON p.station_id = s.id WHERE a.deleted = 0 AND DATE(a.abnormal_time) BETWEEN #{startTime} AND #{endTime}
AND s.id = #{stationId}
GROUP BY a.abnormal_type ) t CROSS JOIN ( SELECT COUNT(a.id) AS totalCount FROM abnormal_order a LEFT JOIN order_list o ON a.order_code = o.order_code COLLATE utf8mb4_unicode_ci LEFT JOIN charging_pile p ON o.pile_code = p.pile_code COLLATE utf8mb4_unicode_ci LEFT JOIN charging_station s ON p.station_id = s.id WHERE a.deleted = 0 AND DATE(a.abnormal_time) BETWEEN #{startTime} AND #{endTime}
AND s.id = #{stationId}
) total
